import assert from 'node:assert/strict';
import { randomUUID } from 'node:crypto';
import { scriptDatabase } from './env';

// Opt-in integration check. Uses the running local production server and real Supabase.
// Only the fresh profiles generated by this script are deleted in cleanup.
async function main() {
  const db = scriptDatabase();
  const base = process.env.SMOKE_APP_URL || 'http://localhost:3000';
  const ownedProfiles: string[] = [];
  let cookie = '';
  async function request<T = Record<string, unknown>>(
    path: string,
    body?: Record<string, unknown>,
    cookieOverride?: string,
  ) {
    const response = await fetch(`${base}/api/${path}`, {
      method: body ? 'POST' : 'GET',
      headers: {
        ...(body ? { 'Content-Type': 'application/json' } : {}),
        Cookie: cookieOverride ?? cookie,
      },
      body: body ? JSON.stringify(body) : undefined,
      signal: AbortSignal.timeout(60000),
    });
    const data = await response.json();
    if (!response.ok)
      throw new Error(
        `API ${path} failed (${response.status}): ${data.code || 'unknown'}`,
      );
    return { data: data as T, response };
  }
  try {
    const candidate = randomUUID();
    const bootstrap = await request<{
      userId: string;
      sessionId: string;
      levels: { count: number }[];
    }>('bootstrap', { id: randomUUID(), browserId: candidate });
    assert.equal(bootstrap.data.userId, candidate);
    ownedProfiles.push(candidate);
    cookie = bootstrap.response.headers
      .getSetCookie()
      .map((value) => value.split(';')[0])
      .join('; ');
    assert.match(cookie, /mathmate_browser=/);
    assert.equal(bootstrap.data.levels.length, 14);
    assert.equal(
      bootstrap.data.levels.reduce((sum, level) => sum + level.count, 0),
      1550,
    );
    const sessionId = bootstrap.data.sessionId;
    const resumed = await request<{ userId: string; sessionId: string }>(
      'bootstrap',
      { id: randomUUID(), browserId: randomUUID(), sessionId },
    );
    assert.equal(resumed.data.userId, candidate);
    assert.equal(resumed.data.sessionId, sessionId);
    const { data: list } = await request<{
      problems: { id: string; answer_value?: string; solution?: string }[];
    }>('problems?level=4&limit=150');
    assert.equal(list.problems.length, 50);
    assert.equal(list.problems[0].answer_value, undefined);
    assert.equal(list.problems[0].solution, undefined);
    const { data: expected, error: expectedError } = await db
      .from('problems')
      .select('answer_value')
      .eq('id', list.problems[0].id)
      .single();
    assert.equal(expectedError, null);
    const attemptId = randomUUID();
    const context = () => ({
      id: randomUUID(),
      sessionId,
      attemptId,
      occurredAt: new Date().toISOString(),
    });
    const startBody = { ...context(), problemId: list.problems[0].id };
    const started = await request<{ steps: { id: string }[] }>(
      'attempts',
      startBody,
    );
    await request('attempts', startBody);
    assert.ok(started.data.steps.length >= 2);
    await request('mode', { ...context(), mode: 'guided' });
    await request('steps', { ...context(), stepId: started.data.steps[0].id });
    const incorrect = await request<{ isCorrect: boolean }>('submissions', {
      ...context(),
      answer: 'definitely-not-the-answer',
    });
    assert.equal(incorrect.data.isCorrect, false);
    const answerBody = { ...context(), answer: ` ${expected.answer_value} ` };
    const correct = await request<{
      isCorrect: boolean;
      submissionNumber: number;
    }>('submissions', answerBody);
    assert.equal(correct.data.isCorrect, true);
    assert.equal(correct.data.submissionNumber, 2);
    await request('submissions', answerBody);
    const revealed = await request<{ answer: string }>('answer', context());
    assert.equal(revealed.data.answer, expected.answer_value);
    const heartbeat = {
      id: randomUUID(),
      type: 'activity_heartbeat',
      occurredAt: new Date().toISOString(),
      attemptId,
      activeMs: 1000,
      payload: { visible: true, focused: true },
    };
    await request('events', { sessionId, events: [heartbeat] });
    await request('events', { sessionId, events: [heartbeat] });
    await request('events', {
      sessionId,
      events: [
        {
          id: randomUUID(),
          type: 'step_closed',
          occurredAt: new Date().toISOString(),
          attemptId,
          stepId: started.data.steps[0].id,
          payload: { visible_active_ms: 1000 },
        },
      ],
    });

    if (
      !process.argv.includes('--skip-ai') &&
      process.env.npm_config_skip_ai !== 'true'
    ) {
      const chatBody = {
        ...context(),
        threadId: randomUUID(),
        responseId: randomUUID(),
        content:
          'Gi meg ett kort hint på norsk til denne oppgaven, uten å oppgi fasiten.',
      };
      const reply = await request<{
        message: {
          id: string;
          status: string;
          content: string;
          input_tokens: number;
          model: string;
        };
      }>('chat', chatBody);
      assert.equal(reply.data.message.status, 'completed');
      assert.ok(reply.data.message.content.length > 0);
      assert.ok(reply.data.message.input_tokens > 0);
      assert.ok(reply.data.message.model);
      const replay = await request<{ message: { id: string } }>(
        'chat',
        chatBody,
      );
      assert.equal(replay.data.message.id, reply.data.message.id);
      console.log(
        'Live AI reply received, persisted, and replayed without regeneration.',
      );
    }
    await request('leave', { ...context(), reason: 'next_problem' });
    const abandonedId = randomUUID();
    await request('attempts', {
      ...context(),
      attemptId: abandonedId,
      problemId: list.problems[1].id,
    });
    await request('leave', {
      ...context(),
      attemptId: abandonedId,
      reason: 'level_change',
    });
    const { data: stats, error: statsError } = await db
      .from('session_stats')
      .select('*')
      .eq('session_id', sessionId)
      .single();
    assert.equal(statsError, null);
    assert.equal(stats.attempt_count, 2);
    assert.equal(stats.solved_attempt_count, 1);
    assert.equal(stats.distinct_problems_solved, 1);
    assert.equal(stats.submission_count, 2);
    const { data: rows, error: submissionError } = await db
      .from('answer_submissions')
      .select('raw_answer,is_correct,occurred_at,received_at,evaluated_at')
      .eq('attempt_id', attemptId)
      .order('submission_number');
    assert.equal(submissionError, null);
    assert.equal(rows?.length, 2);
    assert.equal(rows![0].raw_answer, 'definitely-not-the-answer');
    assert.equal(rows![1].is_correct, true);
    assert.equal(rows![1].raw_answer, answerBody.answer);
    rows!.forEach((row) => {
      assert.ok(row.occurred_at && row.received_at && row.evaluated_at);
    });
    const { count: heartbeatCount } = await db
      .from('events')
      .select('id', { count: 'exact', head: true })
      .eq('id', heartbeat.id);
    assert.equal(heartbeatCount, 1);

    const renewed = await request<{ userId: string; sessionId: string }>(
      'bootstrap',
      { id: randomUUID(), browserId: candidate, sessionId, renew: true },
    );
    assert.equal(renewed.data.userId, candidate);
    assert.notEqual(renewed.data.sessionId, sessionId);
    const { data: closedSession } = await db
      .from('sessions')
      .select('ended_at,end_reason')
      .eq('id', sessionId)
      .single();
    assert.ok(closedSession?.ended_at);
    assert.equal(closedSession?.end_reason, 'inactivity');

    const otherCandidate = randomUUID();
    const other = await request<{ userId: string }>(
      'bootstrap',
      { id: randomUUID(), browserId: otherCandidate },
      '',
    );
    assert.equal(other.data.userId, otherCandidate);
    ownedProfiles.push(otherCandidate);
    const otherCookie = other.response.headers
      .getSetCookie()
      .map((value) => value.split(';')[0])
      .join('; ');
    const forbidden = await fetch(`${base}/api/answer`, {
      method: 'POST',
      headers: { Cookie: otherCookie, 'Content-Type': 'application/json' },
      body: JSON.stringify(context()),
    });
    assert.equal(forbidden.status, 404);
    const tampered = await fetch(`${base}/api/submissions`, {
      method: 'POST',
      headers: { Cookie: cookie, 'Content-Type': 'application/json' },
      body: JSON.stringify({ ...context(), answer: '0', isCorrect: true }),
    });
    assert.equal(tampered.status, 400);
    console.log(
      'PASS: real Supabase HTTP flow, 1,550 questions, answer/step/chat logs, timestamps, statistics, retries and browser isolation.',
    );
  } finally {
    if (
      process.argv.includes('--keep-data') ||
      process.env.npm_config_keep_data === 'true'
    )
      console.log(
        'Smoke-check profiles retained for inspection:',
        ownedProfiles,
      );
    else
      for (const id of ownedProfiles) {
        const { error } = await db.from('app_users').delete().eq('id', id);
        if (error)
          throw new Error(
            'Could not clean up a generated smoke-check profile.',
          );
      }
  }
}
main().catch((error: unknown) => {
  console.error(error instanceof Error ? error.message : 'Smoke check failed.');
  process.exitCode = 1;
});
